// Gather all inputs
const salesNoB = $('Sales Without B-Label').all().map(i => i.json);
const unsure = $('Unsure Labels').all().map(i => i.json);
const misclass = $('Misclassified Check').all().map(i => i.json);
const auditRows = $('Audit Sheet - Suppressed').all().map(i => i.json);

// Filter audit rows to last 24h and find suppressed ones
const now = new Date();
const cutoff = new Date(now - 24 * 60 * 60 * 1000);
const suppressed = auditRows.filter(r => {
  if (!r.timestamp) return false;
  const t = new Date(r.timestamp);
  return t >= cutoff && r.suppress_reason && r.suppress_reason !== '';
});

// Build report sections
let report = '# Daily Triage Watchdog \u2014 ' + now.toISOString().split('T')[0] + '\n\n';

// Section 1: Sales emails with no B-label
report += '## Sales Emails With No B-Label (no draft created)\n\n';
if (salesNoB.length === 0 || (salesNoB.length === 1 && !salesNoB[0].id)) {
  report += '_None today \u2014 all Sales emails got a B-label._\n\n';
} else {
  const validSales = salesNoB.filter(m => m.id);
  report += `**${validSales.length} emails** sitting with TAG-SYS/Sales but no sub-route:\n\n`;
  for (const m of validSales) {
    const from = m.From || m.from || 'Unknown';
    const subj = m.Subject || m.subject || 'No subject';
    const snippet = (m.snippet || m.textPlain || '').substring(0, 150);
    report += `- **${from}**: ${subj}\n  _${snippet}_\n\n`;
  }
}

// Section 2: Unsure emails
report += '## Unsure Classifications\n\n';
if (unsure.length === 0 || (unsure.length === 1 && !unsure[0].id)) {
  report += '_None today._\n\n';
} else {
  const validUnsure = unsure.filter(m => m.id);
  report += `**${validUnsure.length} emails** classified as Unsure:\n\n`;
  for (const m of validUnsure) {
    const from = m.From || m.from || 'Unknown';
    const subj = m.Subject || m.subject || 'No subject';
    report += `- **${from}**: ${subj}\n`;
  }
  report += '\n';
}

// Section 3: Possible misclassifications
report += '## Possible Misclassifications (automated senders tagged as Sales)\n\n';
if (misclass.length === 0 || (misclass.length === 1 && !misclass[0].id)) {
  report += '_None detected._\n\n';
} else {
  const validMis = misclass.filter(m => m.id);
  report += `**${validMis.length} emails** from automated/noreply senders got Sales label:\n\n`;
  for (const m of validMis) {
    const from = m.From || m.from || 'Unknown';
    const subj = m.Subject || m.subject || 'No subject';
    report += `- **${from}**: ${subj}\n`;
  }
  report += '\n';
}

// Section 4: Suppressed drafts
report += '## Suppressed Drafts (last 24h)\n\n';
if (suppressed.length === 0) {
  report += '_None suppressed._\n\n';
} else {
  report += `**${suppressed.length} drafts** were suppressed:\n\n`;
  for (const r of suppressed.slice(0, 20)) {
    report += `- Thread ${r.thread_id || 'unknown'}: ${r.suppress_reason || 'unknown reason'}\n`;
  }
  report += '\n';
}

// Build Claude prompt
let prompt = '---\n\n## Claude Prompt\n\nCopy-paste the section below into Claude:\n\n---\n\n';
prompt += '```\n';
prompt += 'Here is my daily Email Triage Watchdog report. For each section, tell me:\n\n';
prompt += '1. SALES WITH NO B-LABEL: For each email, what B-label should it have gotten? ';
prompt += 'Should I adjust the classifier prompt, lower the confidence threshold, or is this a bug?\n\n';
prompt += '2. UNSURE: What should each of these have been classified as? ';
prompt += 'What rule change would catch them next time?\n\n';
prompt += '3. MISCLASSIFICATIONS: Confirm which are wrong and suggest specific exclusion rules ';
prompt += 'to add to the classifier prompt.\n\n';
prompt += '4. SUPPRESSED: Are any of these suppressed drafts that actually should have gotten through?\n\n';
prompt += 'After your analysis, give me a prioritized list of changes to make to the Email Triage System.\n\n';
prompt += '--- REPORT DATA ---\n\n';

// Add raw data for Claude
const validSales2 = salesNoB.filter(m => m.id);
for (const m of validSales2) {
  prompt += `SALES NO B-LABEL: From=${m.From || m.from || '?'} | Subject=${m.Subject || m.subject || '?'} | Snippet=${(m.snippet || '').substring(0, 200)}\n`;
}
const validUnsure2 = unsure.filter(m => m.id);
for (const m of validUnsure2) {
  prompt += `UNSURE: From=${m.From || m.from || '?'} | Subject=${m.Subject || m.subject || '?'} | Snippet=${(m.snippet || '').substring(0, 200)}\n`;
}
const validMis2 = misclass.filter(m => m.id);
for (const m of validMis2) {
  prompt += `MISCLASS: From=${m.From || m.from || '?'} | Subject=${m.Subject || m.subject || '?'} | Snippet=${(m.snippet || '').substring(0, 200)}\n`;
}
for (const r of suppressed.slice(0, 20)) {
  prompt += `SUPPRESSED: Thread=${r.thread_id || '?'} | Reason=${r.suppress_reason || '?'}\n`;
}
prompt += '```\n';

return [{ json: { report: report + prompt, subject: 'Triage Watchdog \u2014 ' + now.toISOString().split('T')[0], salesCount: validSales2.length, unsureCount: validUnsure2.length, misclassCount: validMis2.length, suppressedCount: suppressed.length } }];
